namespace ghidra.trace.database.symbol;





using ghidra.program.model.symbol;
using ghidra.trace.model.symbol;
using ghidra.util;
using ghidra.util;
using ghidra.util.database;
using ghidra.util.database;

public abstract class AbstractDBTraceSymbolSingleTypeView<T> where T : AbstractDBTraceSymbol {

	protected DBTraceSymbolManager manager;
	protected byte typeID;
	protected DBCachedObjectStore<T> store;

	protected Collection<T> view;
	protected DBCachedObjectIndex<Long, T> symbolsByParentID;
	protected DBCachedObjectIndex<string, T> symbolsByName;

	public AbstractDBTraceSymbolSingleTypeView(DBTraceSymbolManager manager, byte typeID,
			DBCachedObjectStore<T> store) {
		this.manager = manager;
		this.typeID = typeID;
		this.store = store;

		this.view = constructView();
		this.symbolsByParentID = store.getIndex(typeof(long), AbstractDBTraceSymbol.PARENT_COLUMN);
		this.symbolsByName = store.getIndex(typeof(string), AbstractDBTraceSymbol.NAME_COLUMN);
	}

	protected Collection<T> constructView() {
		return Collections.unmodifiableCollection(store.asMap().values());
	}

	public DBTraceSymbolManager getManager() {
		return manager;
	}

	// TODO: A place to store/manager/generate/whatever dynamic symbols
	// TODO: Do I generate them, or am I given them?
	public Collection<T> getAll(bool includeDynamicSymbols) {
		return view;
	}

	public Collection<T> getChildrenNamed(string name, TraceNamespaceSymbol parent) {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			DBTraceNamespaceSymbol dbnsParent =
				manager.assertIsMine((Namespace) Objects.requireNonNull(parent));
			return symbolsByParentID.get(dbnsParent.getID())
					.stream()
					.filter(s => name.equals(s.name))
					.collect(Collectors.toUnmodifiableList());
		}
	}

	public Collection<T> getChildren(TraceNamespaceSymbol parent) {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			DBTraceNamespaceSymbol dbnsParent = manager.assertIsMine((Namespace) parent);
			return Collections.unmodifiableCollection(symbolsByParentID.get(dbnsParent.getID()));
		}
	}

	public Collection<T> getNamed(string name) {
		return Collections.unmodifiableCollection(symbolsByName.get(name));
	}

	public Collection<T> getWithMatchingName(string glob, bool caseSensitive) {
		Predicate<string> predicate =
			UserSearchUtils.createSearchPattern(glob, caseSensitive).asPredicate();
		return view.stream().filter(s => predicate.test(s.name)).toList();
	}

	public Iterator<T> scanByName(string startName) {
		return symbolsByName.tail(startName, true).values().iterator();
	}

	public T getByKey(long key) {
		return store.getObjectAt(key);
	}

	public void invalidateCache() {
		store.invalidateCache();
	}
}
